content.content:
1	@use "../abstract" as *;
2	
3	.no-filter-bar {
4	  position: relative;
5	  z-index: var(--z-index-sticky-filter);
6	  pointer-events: auto;
7	  display: flex;
8	  justify-content: space-between;
9	  align-items: center;
10	  gap: var(--gutter-md);
11	  @include mq(lg) {
12	    flex-direction: column;
13	  }
14	  &__group {
15	    display: flex;
16	    align-items: center;
17	    gap: var(--gutter-sm);
18	    pointer-events: auto;
19	    width: 100%;
20	    @include mq(lg) {
21	      > div {
22	        width: 100%;
23	      }
24	    }
25	  }
26	  &__search {
27	    flex: 1;
28	    justify-content: flex-end;
29	    display: flex;
30	    pointer-events: auto;
31	    width: 100%;
32	    @include mq(lg) {
33	      > div {
34	        max-width: inherit;
35	      }
36	    }
37	  }
38	}
39	
40	.no-form {
41	  $root: &;
42	
43	  &-container {
44	    display: flex;
45	    flex-direction: column;
46	    gap: var(--gutter-md);
47	  }
48	  &-group {
49	    display: flex;
50	    flex-direction: column;
51	    gap: var(--gutter-md);
52	    padding: var(--gutter-xl) 0;
53	    border-bottom: 1px solid var(--clr-border-default);
54	  }
55	  &-head {
56	    display: flex;
57	    flex-direction: column;
58	    align-items: flex-start;
59	    gap: var(--gutter-md);
60	  }
61	  &-body {
62	    display: flex;
63	    flex-direction: column;
64	    gap: var(--gutter-md);
65	    @include mq(md) {
66	      gap: var(--gutter-sm);
67	    }
68	  }
69	  &-wrap {
70	    display: flex;
71	    flex-direction: column;
72	  }
73	  &-list {
74	    display: flex;
75	    flex-wrap: wrap;
76	    gap: var(--gutter-xs);
77	  }
78	  &-item {
79	    position: relative;
80	    flex: 1 1 25rem;
81	    max-width: 100%;
82	
83	    input[type="checkbox"],
84	    input[type="radio"] {
85	      position: absolute;
86	      opacity: 0;
87	      pointer-events: none;
88	    }
89	    label {
90	      display: inline-flex;
91	      align-items: center;
92	      justify-content: center;
93	      width: 100%;
94	      backdrop-filter: blur(24px);
95	      -webkit-backdrop-filter: blur(24px);
96	      height: calc(var(--input-height) * 2);
97	      padding-inline: var(--gutter-md);
98	      border: 1px solid var(--clr-border-default);
99	      background: var(--form-choice-surface);
100	      box-shadow: var(--form-choice-shadow);
101	      color: var(--clr-text-title);
102	      @include font("f-heading-5");
103	      white-space: nowrap;
104	      cursor: pointer;
105	      transition:
106	        var(--form-control-transition),
107	        var(--form-control-shadow-transition),
108	        transform var(--duration-fast) var(--ease-smooth);
109	
110	      @include mq(md) {
111	        height: var(--input-height);
112	        @include font("f-body-1");
113	      }
114	    }
115	
116	    input[type="checkbox"]:checked + label,
117	    input[type="radio"]:checked + label {
118	      border-color: var(--clr-border-strong);
119	      background: var(--form-choice-surface-active);
120	      color: var(--clr-text-title);
121	      box-shadow: var(--form-choice-shadow-active);
122	    }
123	
124	    input[type="checkbox"]:focus-visible + label,
125	    input[type="radio"]:focus-visible + label {
126	      outline: var(--form-focus-ring-width) solid var(--clr-border-strong);
127	      outline-offset: 2px;
128	      box-shadow: var(--form-choice-shadow-focus);
129	    }
130	
131	    @media (hover: hover) and (pointer: fine) {
132	      input[type="checkbox"]:not(:checked) + label:hover,
133	      input[type="radio"]:not(:checked) + label:hover {
134	        border-color: var(--clr-border-strong);
135	        background: var(--form-choice-surface-hover);
136	        box-shadow: var(--form-choice-shadow-hover);
137	      }
138	    }
139	
140	    label:active {
141	      background: var(--form-choice-surface-press);
142	      box-shadow: var(--form-choice-shadow-press);
143	      transform: translate3d(0, 1px, 0);
144	    }
145	  }
146	
147	  &-reveal {
148	    width: 100%;
149	    max-height: 0;
150	    opacity: 0;
151	    overflow: clip;
152	    pointer-events: none;
153	    transform: translateY(fluid(10, 16));
154	    filter: blur(8px);
155	    transition:
156	      max-height calc(var(--duration-default) + 120ms) var(--ease-snappy),
157	      opacity calc(var(--duration-default) + 60ms) var(--ease-smooth),
158	      transform calc(var(--duration-default) + 60ms) var(--ease-snappy),
159	      filter calc(var(--duration-default) + 60ms) var(--ease-smooth);
160	
161	    &--project-other {
162	      margin-top: var(--gutter-xs);
163	    }
164	
165	    &.is-active {
166	      max-height: fluid(120, 168);
167	      opacity: 1;
168	      pointer-events: auto;
169	      transform: translateY(0);
170	      filter: blur(0);
171	    }
172	  }
173	
174	  &-fields {
175	    display: grid;
176	    grid-template-columns: repeat(2, minmax(0, 1fr));
177	    gap: var(--gutter-md);
178	    @include mq(md) {
179	      grid-template-columns: 1fr;
180	      gap: var(--gutter-sm);
181	    }
182	  }
183	
184	  &-field {
185	    display: flex;
186	    flex-direction: column;
187	    gap: var(--gutter-xs);
188	
189	    label {
190	      color: var(--clr-text-title);
191	    }
192	
193	    &__control {
194	      position: relative;
195	      display: block;
196	      line-height: 0;
197	
198	      .no-form-field__corner {
199	        inset: 0;
200	        color: var(--clr-border-default);
201	        transition:
202	          inset var(--transition-default),
203	          color var(--transition-default);
204	      }
205	
206	      &:focus-within .no-form-field__corner {
207	        inset: 0;
208	        color: var(--clr-border-strong);
209	      }
210	    }
211	
212	    input,
213	    textarea {
214	      display: block;
215	      width: 100%;
216	      border: 1px solid var(--clr-border-default);
217	      background: var(--form-control-surface);
218	      box-shadow: var(--form-control-shadow-base);
219	      color: var(--clr-text-title);
220	      @include font("f-body-2");
221	      transition:
222	        var(--form-control-transition), var(--form-control-shadow-transition);
223	
224	      &::placeholder {
225	        color: var(--clr-text-body);
226	        opacity: var(--form-placeholder-opacity);
227	      }
228	
229	      @media (hover: hover) and (pointer: fine) {
230	        &:hover {
231	          border-color: var(--form-control-border-hover);
232	          background: var(--form-control-surface-hover);
233	          box-shadow: var(--form-control-shadow-hover);
234	        }
235	      }
236	
237	      &:focus-visible {
238	        outline: none;
239	        border-color: var(--clr-border-strong);
240	        background: var(--form-control-surface-active);
241	        box-shadow: var(--form-control-shadow-focus);
242	      }
243	
244	      &:active {
245	        background: var(--form-control-surface-press);
246	      }
247	    }
248	
249	    input {
250	      height: var(--input-height);
251	      padding-inline: var(--gutter-sm);
252	    }
253	
254	    &--inline {
255	      width: 100%;
256	      align-self: stretch;
257	    }
258	
259	    &--file {
260	      #{$root}-file-row {
261	        display: grid;
262	        grid-template-columns: 1fr auto;
263	        gap: var(--gutter-sm);
264	        align-items: center;
265	      }
266	
267	      #{$root}-file-placeholder {
268	        display: flex;
269	        align-items: center;
270	        height: var(--input-height);
271	        padding-inline: var(--gutter-sm);
272	        padding-right: var(--gutter-2xl);
273	        color: var(--clr-text-body);
274	        pointer-events: none;
275	        border: 1px solid var(--clr-border-default);
276	        background: var(--form-control-surface);
277	        box-shadow: var(--form-control-shadow-base);
278	        overflow: hidden;
279	        text-overflow: ellipsis;
280	        white-space: nowrap;
281	        transition:
282	          var(--form-control-transition), var(--form-control-shadow-transition);
283	      }
284	
285	      #{$root}-field__control input[type="file"] {
286	        position: absolute;
287	        inset: 0;
288	        opacity: 0;
289	        cursor: pointer;
290	      }
291	
292	      #{$root}-file-clear {
293	        position: absolute;
294	        right: var(--gutter-xs);
295	        top: 50%;
296	        transform: translateY(-50%);
297	        width: var(--form-file-action-size);
298	        height: var(--form-file-action-size);
299	        border: 1px solid var(--clr-border-default);
300	        background: var(--form-control-surface);
301	        color: var(--clr-text-body);
302	        display: none;
303	        align-items: center;
304	        justify-content: center;
305	        cursor: pointer;
306	        z-index: 1;
307	        transition:
308	          var(--form-control-transition),
309	          var(--form-control-shadow-transition),
310	          transform var(--duration-fast) var(--ease-smooth);
311	
312	        i {
313	          font-size: fluid(10, 12);
314	          line-height: 1;
315	          pointer-events: none;
316	        }
317	      }
318	
319	      #{$root}-file-clear:not([hidden]) {
320	        display: inline-flex;
321	      }
322	
323	      #{$root}-file-button {
324	        display: inline-flex;
325	        align-items: center;
326	        justify-content: center;
327	        height: var(--input-height);
328	        padding-inline: var(--gutter-md);
329	        border: 1px solid var(--clr-border-default);
330	        background: var(--form-control-surface);
331	        color: var(--clr-text-title);
332	        cursor: pointer;
333	        box-shadow: var(--form-control-shadow-base);
334	        transition:
335	          var(--form-control-transition),
336	          var(--form-control-shadow-transition),
337	          transform var(--duration-fast) var(--ease-smooth);
338	      }
339	
340	      @media (hover: hover) and (pointer: fine) {
341	        #{$root}-file-button:hover {
342	          border-color: var(--clr-border-strong);
343	          background: var(--form-control-surface-hover);
344	          box-shadow: var(--form-control-shadow-hover);
345	        }
346	
347	        #{$root}-file-clear:hover {
348	          border-color: var(--clr-border-strong);
349	          background: var(--form-control-surface-hover);
350	          box-shadow: var(--form-control-shadow-hover);
351	          color: var(--clr-text-title);
352	        }
353	      }
354	
355	      #{$root}-file-button:active,
356	      #{$root}-file-clear:active {
357	        background: var(--form-control-surface-press);
358	        transform: translate3d(0, 1px, 0);
359	      }
360	
361	      #{$root}-field__control:focus-within {
362	        #{$root}-file-placeholder {
363	          border-color: var(--clr-border-strong);
364	          background: var(--form-control-surface-active);
365	          box-shadow: var(--form-control-shadow-focus);
366	        }
367	      }
368	    }
369	
370	    textarea {
371	      min-height: fluid(160, 320);
372	      padding: var(--gutter-sm);
373	      resize: vertical;
374	    }
375	  }
376	
377	  &-policy {
378	    display: inline-flex;
379	    align-items: center;
380	    gap: var(--gutter-xs);
381	    width: fit-content;
382	    color: var(--clr-text-title);
383	    cursor: pointer;
384	
385	    input[type="checkbox"] {
386	      @include blind();
387	    }
388	
389	    &__check {
390	      position: relative;
391	      width: fluid(16, 24);
392	      height: fluid(16, 24);
393	      border: 1px solid var(--clr-border-default);
394	      background: var(--form-control-surface);
395	      display: inline-grid;
396	      place-items: center;
397	      color: var(--clr-white-100);
398	      cursor: pointer;
399	      box-shadow: var(--form-control-shadow-base);
400	      transition:
401	        var(--form-control-transition),
402	        var(--form-control-shadow-transition),
403	        transform var(--duration-fast) var(--ease-smooth);
404	
405	      svg {
406	        width: 70%;
407	        height: 70%;
408	        transform: scale(0);
409	        opacity: 0;
410	        transform-origin: center;
411	        transition:
412	          transform var(--duration-default) var(--ease-smooth),
413	          opacity var(--duration-default) var(--ease-smooth);
414	      }
415	    }
416	
417	    input[type="checkbox"]:checked + #{$root}-policy__check {
418	      border-color: var(--clr-border-strong);
419	      background: var(--form-control-surface-active);
420	      box-shadow: var(--form-control-shadow-hover);
421	    }
422	
423	    input[type="checkbox"]:checked + #{$root}-policy__check svg {
424	      transform: scale(1);
425	      opacity: 1;
426	    }
427	
428	    input[type="checkbox"]:focus-visible + #{$root}-policy__check {
429	      outline: 2px solid var(--clr-border-strong);
430	      outline-offset: 2px;
431	      box-shadow: var(--form-control-shadow-focus);
432	    }
433	
434	    @media (hover: hover) and (pointer: fine) {
435	      &:hover #{$root}-policy__check {
436	        border-color: var(--clr-border-strong);
437	        background: var(--form-control-surface-hover);
438	        box-shadow: var(--form-control-shadow-hover);
439	      }
440	    }
441	
442	    &:active #{$root}-policy__check {
443	      background: var(--form-control-surface-press);
444	      transform: translate3d(0, 1px, 0);
445	    }
446	
447	    &__text {
448	      color: var(--clr-text-body);
449	
450	      a {
451	        color: var(--clr-text-title);
452	        text-decoration: underline;
453	        text-underline-offset: 3px;
454	      }
455	    }
456	  }
457	
458	  &-submit {
459	    display: flex;
460	    justify-content: center;
461	    margin-top: var(--gutter-xl);
462	
463	    &__button {
464	      justify-content: center;
465	      width: fluid(188, 376);
466	      @include font("f-heading-3");
467	      font-weight: 400;
468	    }
469	  }
470	
471	  &-error {
472	    margin-top: var(--gutter-2xs);
473	    min-height: var(--gutter-md);
474	    color: var(--clr-text-error);
475	
476	    &.is-empty {
477	      visibility: hidden;
478	    }
479	  }
480	
481	  @include mq(md) {
482	    &-item {
483	      flex-basis: calc(50% - (var(--gutter-xs) / 2));
484	    }
485	
486	    &-reveal.is-active {
487	      max-height: fluid(132, 176);
488	    }
489	  }
490	
491	  @include mq(sm) {
492	    &-item {
493	      flex-basis: 100%;
494	    }
495	
496	    &-field--inline {
497	      width: 100%;
498	    }
499	  }
500	}
501	
502	// =============================================================================
503	// Wizard — 단계별 폼 UI
504	// =============================================================================
505	
506	.no-wizard {
507	  flex: 1;
508	  display: grid;
509	  grid-template-columns: minmax(280px, 340px) minmax(0, 1fr);
510	  gap: var(--gutter-xl);
511	  height: 100%;
512	  min-height: 0;
513	  overflow: hidden;
514	  padding: var(--gutter-xl) 0 var(--gutter-2xl);
515	
516	  &-sidebar {
517	    display: flex;
518	    min-height: 0;
519	    overflow: hidden;
520	
521	    &__inner {
522	      display: flex;
523	      flex-direction: column;
524	      gap: var(--gutter-md);
525	      flex: 1 1 auto;
526	      min-height: 0;
527	      overflow: hidden;
528	    }
529	
530	    &__status {
531	      order: 1;
532	      display: flex;
533	      flex-direction: column;
534	      gap: var(--gutter-xs);
535	    }
536	
537	    &__counter {
538	      display: flex;
539	      align-items: baseline;
540	      gap: var(--gutter-2xs);
541	    }
542	
543	    &__current {
544	      font-family: var(--family-en-title);
545	      color: var(--clr-text-title);
546	      line-height: 0.92;
547	    }
548	
549	    &__sep,
550	    &__total {
551	      font-family: var(--family-en-title);
552	      color: var(--clr-text-desc);
553	    }
554	
555	    &__progress {
556	      flex: 0 0 auto;
557	      min-height: auto;
558	    }
559	  }
560	
561	  &-overview {
562	    order: 2;
563	    flex: 1 1 0;
564	    min-height: 0;
565	    display: flex;
566	    flex-direction: column;
567	    overflow: hidden;
568	
569	    &__list {
570	      flex: 1 1 0;
571	      min-height: 0;
572	      display: flex;
573	      flex-direction: column;
574	      gap: var(--gutter-md);
575	      overflow-y: auto;
576	      overflow-x: hidden;
577	      overscroll-behavior: contain;
578	      -webkit-overflow-scrolling: touch;
579	      padding-block: var(--gutter-2xs);
580	      padding-inline-end: var(--gutter-2xs);
581	    }
582	
583	    &__item {
584	      opacity: 0.4;
585	      transition: opacity var(--duration-default) var(--ease-smooth);
586	
587	      &.is-available {
588	        opacity: 0.8;
589	      }
590	
591	      &.is-current {
592	        opacity: 1;
593	      }
594	    }
595	
596	    &__button {
597	      position: relative;
598	      width: 100%;
599	      min-width: 0;
600	      display: flex;
601	      flex-direction: column;
602	      align-items: flex-start;
603	      gap: var(--gutter-2xs);
604	      padding: fluid(18, 22);
605	      border: 1px solid color-mix(in srgb, var(--clr-white-100) 6%, transparent);
606	      background: color-mix(in srgb, var(--clr-white-100) 2%, transparent);
607	      overflow: hidden;
608	      text-align: left;
609	      cursor: pointer;
610	      transition:
611	        border-color var(--duration-default) var(--ease-smooth),
612	        background-color var(--duration-default) var(--ease-smooth),
613	        transform var(--duration-default) var(--ease-smooth);
614	
615	      &:disabled {
616	        cursor: default;
617	      }
618	
619	      &.is-framed {
620	        justify-content: flex-start;
621	        min-height: auto;
622	        border-color: color-mix(in srgb, var(--clr-white-100) 10%, transparent);
623	        background: color-mix(in srgb, var(--clr-white-100) 4%, transparent);
624	        backdrop-filter: blur(10px);
625	        -webkit-backdrop-filter: blur(10px);
626	      }
627	    }
628	
629	    &__head {
630	      position: relative;
631	      z-index: 1;
632	      display: inline-flex;
633	      align-items: center;
634	      gap: 0;
635	      min-width: 0;
636	    }
637	
638	    &__rect {
639	      flex: 0 0 auto;
640	      width: 0;
641	      margin-right: 0;
642	      overflow: hidden;
643	      opacity: 0;
644	      transform: translate3d(-8px, 0, 0) scale(0.92);
645	      transition:
646	        width var(--duration-default) var(--ease-smooth),
647	        margin-right var(--duration-default) var(--ease-smooth),
648	        opacity var(--duration-default) var(--ease-smooth),
649	        transform var(--duration-default) var(--ease-smooth);
650	
651	      span {
652	        animation-play-state: paused;
653	      }
654	    }
655	
656	    &__index {
657	      display: inline-flex;
658	      align-items: center;
659	      font-family: var(--family-en-title);
660	      color: var(--clr-text-desc);
661	      line-height: 1;
662	      letter-spacing: 0.08em;
663	      text-transform: uppercase;
664	      white-space: nowrap;
665	    }
666	
667	    &__body {
668	      position: relative;
669	      z-index: 1;
670	      min-width: 0;
671	      width: 100%;
672	      display: flex;
673	      flex-direction: column;
674	      gap: var(--gutter-3xs);
675	    }
676	
677	    &__corner {
678	      color: color-mix(in srgb, var(--clr-white-100) 22%, transparent);
679	      opacity: 0;
680	      transition:
681	        opacity var(--duration-default) var(--ease-smooth),
682	        color var(--duration-default) var(--ease-smooth);
683	    }
684	
685	    &__value {
686	      min-width: 0;
687	      width: 100%;
688	      color: var(--clr-text-desc);
689	      line-height: 1.4;
690	      overflow: hidden;
691	      text-overflow: ellipsis;
692	      white-space: normal;
693	
694	      &.is-chip-list {
695	        display: flex;
696	        flex-wrap: wrap;
697	        gap: var(--gutter-2xs);
698	        position: relative;
699	        width: 100%;
700	        max-width: 100%;
701	      }
702	    }
703	
704	    &__chip-list {
705	      display: flex;
706	      flex-wrap: wrap;
707	      gap: var(--gutter-2xs);
708	      width: 100%;
709	      max-width: 100%;
710	      position: relative;
711	    }
712	
713	    &__chip {
714	      display: inline-flex;
715	      flex: 0 1 auto;
716	      align-items: center;
717	      max-width: 100%;
718	      min-height: fluid(24, 28);
719	      padding-inline: fluid(8, 10);
720	      border: 1px solid
721	        color-mix(in srgb, var(--clr-white-100) 14%, transparent);
722	      background: linear-gradient(
723	        135deg,
724	        color-mix(in srgb, var(--clr-white-100) 10%, transparent),
