342	      this._root.querySelector<HTMLElement>("[data-wizard-current]");
343	    const barElement = this._root.querySelector<HTMLElement>("[data-wizard-bar]");
344	
345	    if (currentElement) {
346	      currentElement.textContent = String(this._current + 1).padStart(2, "0");
347	    }
348	
349	    if (barElement) {
350	      const scale = (this._current + 1) / this._steps.length;
351	      barElement.style.transform = `scaleX(${scale})`;
352	    }
353	
354	    this._syncActionState(immediate);
355	    this._syncSubmitAvailability();
356	  }
357	
358	  private _syncActionState(immediate = false): void {
359	    const isFirstStep = this._current === 0;
360	    const isLastStep = this._current === this._steps.length - 1;
361	
362	    this._prevButtons.forEach((button) => {
363	      this._syncPreviousAction(button, isFirstStep, immediate);
364	    });
365	
366	    this._primaryActionButtons.forEach((button) => {
367	      this._syncPrimaryAction(button, isLastStep);
368	    });
369	  }
370	
371	  private _syncPreviousAction(
372	    button: HTMLButtonElement,
373	    isFirstStep: boolean,
374	    immediate = false,
375	  ): void {
376	    const target = this._resolvePreviousActionTarget(button);
377	    this._clearPreviousActionHideTimer(target);
378	
379	    if (isFirstStep) {
380	      button.disabled = true;
381	      button.setAttribute("aria-disabled", "true");
382	      target.setAttribute("aria-hidden", "true");
383	      target.toggleAttribute("inert", true);
384	
385	      if (
386	        immediate ||
387	        target.hidden ||
388	        target.classList.contains(INIT_DOM_CLASSES.boxHidden)
389	      ) {
390	        this._hidePreviousActionImmediately(target);
391	        return;
392	      }
393	
394	      this._hidePreviousActionWithTransition(target);
395	      return;
396	    }
397	
398	    this._showPreviousActionTarget(target, immediate);
399	    button.disabled = this._submitting;
400	    button.setAttribute(
401	      "aria-disabled",
402	      this._submitting ? "true" : "false",
403	    );
404	  }
405	
406	  private _syncPrimaryAction(
407	    button: HTMLButtonElement,
408	    isSubmitMode: boolean,
409	  ): void {
410	    button.type = isSubmitMode ? "submit" : "button";
411	    button.disabled = this._submitting;
412	    button.classList.toggle("no-wizard-action--next", !isSubmitMode);
413	    button.classList.toggle("no-wizard-action--submit", isSubmitMode);
414	    button.setAttribute("aria-hidden", "false");
415	    button.setAttribute("aria-disabled", this._submitting ? "true" : "false");
416	
417	    if (isSubmitMode) {
418	      button.removeAttribute("data-wizard-next");
419	    } else {
420	      button.dataset.wizardNext = "";
421	    }
422	
423	    const text = button.querySelector<HTMLElement>(".no-corner-btn__text");
424	    if (text) {
425	      const nextLabel = isSubmitMode ? "Submit" : "Next";
426	      if (text.textContent !== nextLabel) {
427	        text.textContent = nextLabel;
428	      }
429	    }
430	  }
431	
432	  private _syncSidebar(): void {
433	    this._syncStepSummaries();
434	    this._syncNavigationState();
435	  }
436	
437	  private _syncNavigationState(): void {
438	    const furthestAccessibleStep = this._resolveFurthestAccessibleStep();
439	
440	    this._navItems.forEach((item, index) => {
441	      const isCurrent = index === this._current;
442	      const isComplete = this._isStepSatisfied(this._steps[index]);
443	      const button = item.querySelector<HTMLButtonElement>(
444	        ".no-wizard-overview__button",
445	      );
446	
447	      item.classList.toggle("is-current", isCurrent);
448	      item.classList.toggle("is-complete", isComplete);
449	      item.classList.toggle("is-available", index <= furthestAccessibleStep);
